def judge(sid, skill, rows):
    from math_kit import with_variants
    return with_variants({"id": sid, "type": "stepwise", "skill": skill}, lambda q, a, why, tag: {"q": q, "parts": [part(B("Your decision?", "তোমাৰ সিদ্ধান্ত?"), B(*ANS[a]), [B(*ANS[1 - a]), B("Both", "দুয়োটা")], why, tag=tag, sid=sid)], "why": why}, rows)


